"""The Radar, memo, email and weekly port against goldens generated by the OLD code (review 019,
``python -m projectzero.ops.parity_radar goldens``): the slot rules (the eighth cut, the >= 65 / >= 55 bars, the
archetype-15 outlier route, dropped, conflict-gated, Research Queue, Watchlist), memo / email variants (each
fundraising timing, Dr / TBD / Founder names, the conflict warning), the weekly window and the document's bytes."""

from __future__ import annotations

import json
from datetime import datetime
from pathlib import Path
from typing import Any

import pytest

from projectzero.ops.parity_radar import CLOCK, WEEKLY, compose_cases, corpus, diff, js, new_pure

GOLDEN: dict[str, Any] = json.loads(
    (Path(__file__).resolve().parents[1] / "fixtures" / "golden_v1" / "oracle_radar.json").read_text(encoding="utf-8")
)
NEW = new_pure(GOLDEN["docs"], GOLDEN["expected"], datetime.fromisoformat(CLOCK).date())


def test_provenance_is_the_clean_old_revision() -> None:
    assert GOLDEN["provenance"]["old_revision"] == "6c739b9cb6ca2517b845e381d39a36c50eccc59e"
    assert GOLDEN["provenance"]["old_dirty"] is False
    assert GOLDEN["provenance"]["clock"] == CLOCK


def test_the_golden_input_is_the_current_corpus() -> None:
    assert json.loads(json.dumps(corpus())) == GOLDEN["docs"]
    assert GOLDEN["input"] == json.loads(json.dumps({"clock": CLOCK, "weekly": WEEKLY, "compose": compose_cases()}))


def test_the_corpus_reaches_every_section() -> None:
    radar = GOLDEN["expected"]["radar"]
    assert [len(radar[k]) for k in ("high", "emerging", "wildcard")] == [8, 1, 1]
    assert all(radar[k] for k in ("research_queue", "gated", "watch"))
    assert GOLDEN["expected"]["credited"] > 0 and GOLDEN["expected"]["credited_again"] == 0
    assert "\r\n" in GOLDEN["expected"]["html"]  # the old file's Windows text-mode bytes


@pytest.mark.parametrize("section", ["radar", "compose", "memo", "email", "weekly", "html"])
def test_section_matches_the_old_code(section: str) -> None:
    assert diff(js(GOLDEN["expected"][section]), NEW[section]) == []
